parameters.inputMappingScript:
// Maps record fields to the Item Row component's inputs.
// Add a line here for every field you add to the row.
map({
	'Title': 'title',
	'Notes': 'notes',
})

parameters.functionScript:
// Paging facts derived from the current page index and the total record count.
// PAGE_SIZE is the one place the page size lives — Limit and Skip are both wired from here.
var PAGE_SIZE = 10;
var page = typeof Inputs.Page === 'number' ? Inputs.Page : 0;
var total = typeof Inputs.Total === 'number' ? Inputs.Total : 0;
if (page < 0) page = 0;
var pages = Math.max(1, Math.ceil(total / PAGE_SIZE));
Outputs.Limit = PAGE_SIZE;
Outputs.Skip = page * PAGE_SIZE;
Outputs.Label = 'Page ' + (page + 1) + ' of ' + pages;
Outputs.HasPrev = page > 0;
Outputs.HasNext = page + 1 < pages;
